 files=own+[str((PUB/f).relative_to(ROOT))for f in ['RESULTS.json','ROOT_INDEPENDENT_AUDIT.json','REPORT.md','CONCLUSIONS.json','DIAGNOSIS.svg']]
 put(D/'PUBLIC_FILES.json',dict(files=files));put(D/'REPORT_COMPLETION.json',summary);put(D/'CODE_BINDING.json',dict(status='pass',pins={f:sha(ROOT/f)for f in own},old_revisions_preserved=True));print('REPORT_COMPLETE')
